from datetime import date as _d

@test("adding months")
def _():
    check_eq(add_months(_d(2026, 1, 31), 1), _d(2026, 2, 28))
    check_eq(add_months(_d(2024, 3, 31), -1), _d(2024, 2, 29))
    check_eq(add_months(_d(2026, 11, 15), 3), _d(2027, 2, 15))
    check_eq(add_months(_d(2026, 1, 15), -13), _d(2024, 12, 15))
    check_eq(add_months(_d(2026, 5, 31), 0), _d(2026, 5, 31))

@test("ages")
def _():
    check_eq(age_on(_d(1990, 6, 15), _d(2026, 6, 14)), 35)
    check_eq(age_on(_d(1990, 6, 15), _d(2026, 6, 15)), 36)
    check_eq(age_on(_d(2000, 2, 29), _d(2026, 2, 28)), 25)
    check_eq(age_on(_d(2000, 2, 29), _d(2026, 3, 1)), 26)

@test("workdays")
def _():
    check_eq(workdays_between(_d(2026, 11, 16), _d(2026, 11, 23)), 5)
    check_eq(workdays_between(_d(2026, 11, 14), _d(2026, 11, 16)), 0)
    check_eq(workdays_between(_d(2026, 11, 1), _d(2026, 12, 1)), 21)
    check_eq(workdays_between(_d(2026, 11, 20), _d(2026, 11, 10)), 0)

@test("next weekday")
def _():
    sunday = _d(2026, 11, 15)
    check_eq(next_weekday(sunday, 0), _d(2026, 11, 16))
    check_eq(next_weekday(sunday, 6), _d(2026, 11, 22))
    check_eq(next_weekday(_d(2026, 11, 16), 0), _d(2026, 11, 23))

